const rev        = $json.rev            || {};
const margin_rev = $json.rev_for_margin || {};
const cogs       = $json.cogs           || {};
const payroll    = $json.payroll        || {};
const cash       = $json.cash           || {};

// --- FORMATTING & SECURITY FUNCTIONS ---
const isAvail = (val) => val !== null && val !== undefined;
const safeNum = (val) => (typeof val === 'number' && !isNaN(val) ? val : 0);

const formatCurrency = (value) => new Intl.NumberFormat('fr-FR', {
  style: 'currency', currency: 'EUR'
}).format(value === 0 ? 0 : value);

const formatDiff = (val) => {
  const sign = val > 0 ? '+' : '';
  return sign + formatCurrency(val);
};

const formatPercentage = (numerator, denominator) => {
  if (!denominator || denominator === 0) return '0.00 %';
  return ((numerator / denominator) * 100).toFixed(2) + ' %';
};

const formatEvo = (numerator, denominator) => {
  if (!denominator || denominator === 0) return '—';
  const val  = (numerator / denominator) * 100;
  const sign = val > 0 ? '+' : '';
  return sign + val.toFixed(2) + ' %';
};

const n = safeNum($json.months_elapsed) || 1;

// --- DATA EXTRACTION & SIGNS INVERSION ---

const b_rev     = safeNum($json.budget_rev);
const b_margin  = safeNum($json.budget_margin);
const b_payroll = safeNum($json.budget_payroll);

const b_rev_annual     = b_rev     * 12;
const b_margin_annual  = b_margin  * 12;
const b_payroll_annual = b_payroll * 12;

const b_rev_cumul     = b_rev     * n;
const b_margin_cumul  = b_margin  * n;
const b_payroll_cumul = b_payroll * n;

const r_cur              = safeNum(rev.cur)   * -1;
const r_prior            = safeNum(rev.prior) * -1;
const r_ytd              = safeNum(rev.ytd)   * -1;
const revenue_prior_available = isAvail(rev.prior);

const rm_cur   = safeNum(margin_rev.cur)   * -1;
const rm_prior = safeNum(margin_rev.prior) * -1;
const rm_ytd   = safeNum(margin_rev.ytd)   * -1;

const c_cur                   = safeNum(cogs.cur);
const c_prior                 = safeNum(cogs.prior);
const c_ytd                   = safeNum(cogs.ytd);
const cogs_prior_available    = isAvail(cogs.prior);
const margin_prior_available  = revenue_prior_available || cogs_prior_available;

const p_cur                    = safeNum(payroll.cur);
const p_prior                  = safeNum(payroll.prior);
const p_ytd                    = safeNum(payroll.ytd);
const payroll_prior_available  = isAvail(payroll.prior);

const cash_cur               = safeNum(cash.cur);
const cash_ytd               = safeNum(cash.ytd);
const cash_prior_available   = isAvail(cash.prior);

// --- CALCULATIONS AND REPORT GENERATION ---

return {
  identifier: $json.identifier,
  data: {
    // --- PERIOD MONTH ---
    revenue_monthly:           formatCurrency(r_cur),
    gross_margin_monthly:      formatCurrency(rm_cur - c_cur),
    gross_margin_rate_monthly: formatPercentage(rm_cur - c_cur, rm_cur),
    payroll_monthly:           formatCurrency(p_cur),
    payroll_rate_monthly:      formatPercentage(p_cur, r_cur),

    // --- EVOLUTION vs M-1 ---
    revenue_prior_available,
    revenue_evo:        revenue_prior_available ? formatEvo(r_cur - r_prior, r_prior) : '—',
    revenue_evo_color:  !revenue_prior_available ? '#868E96' : (r_cur - r_prior) < 0 ? '#C0392B' : '#2D6A4F',
    revenue_diff_value: revenue_prior_available ? formatDiff(r_cur - r_prior) : '—',
    revenue_icon:       revenue_prior_available ? ((r_cur - r_prior) < 0 ? '↓' : '↑') : '',

    margin_prior_available,
    margin_evo:       margin_prior_available ? formatEvo((rm_cur - c_cur) - (rm_prior - c_prior), Math.abs(rm_prior - c_prior)) : '—',
    margin_evo_color: !margin_prior_available ? '#868E96' : ((rm_cur - c_cur) - (rm_prior - c_prior)) < 0 ? '#C0392B' : '#2D6A4F',

    payroll_prior_available,
    payroll_evo:       payroll_prior_available ? formatEvo(p_cur - p_prior, Math.abs(p_prior)) : '—',
    payroll_evo_color: !payroll_prior_available ? '#868E96' : (p_cur - p_prior) > 0 ? '#C0392B' : '#2D6A4F',

    // --- CUMUL ---
    revenue_cumul:           formatCurrency(r_ytd),
    gross_margin_cumul:      formatCurrency(rm_ytd - c_ytd),
    gross_margin_rate_cumul: formatPercentage(rm_ytd - c_ytd, rm_ytd),
    payroll_cumul:           formatCurrency(p_ytd),

    // --- BUDGET (annual displayed, cumulative for variance) ---
    revenue_budget:            formatCurrency(b_rev_annual),
    revenue_budget_diff:       formatDiff(r_ytd - b_rev_cumul),
    revenue_budget_diff_color: (r_ytd - b_rev_cumul) < 0 ? '#C0392B' : '#2D6A4F',

    margin_budget:            formatCurrency(b_margin_annual),
    margin_budget_diff:       formatDiff((rm_ytd - c_ytd) - b_margin_cumul),
    margin_budget_diff_color: ((rm_ytd - c_ytd) - b_margin_cumul) < 0 ? '#C0392B' : '#2D6A4F',

    payroll_budget:            formatCurrency(b_payroll_annual),
    payroll_budget_diff:       formatDiff(p_ytd - b_payroll_cumul),
    payroll_budget_diff_color: (p_ytd - b_payroll_cumul) > 0 ? '#C0392B' : '#2D6A4F',

    // --- CASH ---
    cash_variation_monthly: formatDiff(cash_cur),
    cash_prior_available,
    cash_color:         !cash_prior_available ? '#868E96' : cash_cur < 0 ? '#E06F63' : '#56A884',
    cash_icon:          cash_cur < 0 ? '↓' : '↑',
    cash_total_balance: formatCurrency(cash_ytd),
  }
};

const { entries_month, entries_prior, entries_ytd } = $json;

// --- CONFIGURATION ---
const REVENUE_ROOTS = ["70", "72"];
const MARGIN_REV_ROOTS = ["70", "72", "71"];
const COGS_ROOTS = [
    "601", "602", "6031", "6032", "6037", "604", "605", "607",
    "6081", "6082", "6084", "6085", "6087",
    "6091", "6092", "6094", "6095", "6097", "690"
];
const CASH_ROOTS = ["512", "53"];
const PAYROLL_ROOTS = ["64"];

// --- PRE-AGGREGATION FUNCTION ---
/**
 * Aggregates all entries into a map of totals by root in a single pass.
 * This is the most efficient way to handle large datasets.
 */
const aggregateEntries = (entries) => {
  const totals = {};
  if (!entries?.length) return totals;

  entries.forEach(line => {
    const num = line.account?.toString() || "";
    const balance = Number(line.balance) || 0;

    // Store sum for every possible root length (e.g., "6", "60")
    for (let i = 1; i <= num.length; i++) {
      const root = num.substring(0, i);
      totals[root] = (totals[root] || 0) + balance;
    }
  });
  return totals;
};

const round2 = (n) => Math.round(n * 100) / 100;

// Returns null if no matching root is found, to distinguish "no data" from "zero balance"
const sumFromTotals = (totals, roots) => {
  const hasAnyRoot = roots.some(root => root in totals);
  if (!hasAnyRoot) return null;
  return round2(roots.reduce((sum, root) => sum + (totals[root] || 0), 0));
};

// Derive months elapsed from fy_start (ISO or yyyyMMdd) and $now
const fyDate       = DateTime.fromISO($json.fy_start);
const nowMinus1    = DateTime.now().minus({ months: 1 }).startOf('month');
const months_elapsed = Math.round(nowMinus1.diff(fyDate, 'months').months) + 1;

// Single pass for each period
const totalsCur   = aggregateEntries(entries_month);
const totalsPrior = aggregateEntries(entries_prior);
const totalsYtd   = aggregateEntries(entries_ytd);

return {
    identifier: $json.identifier,
    months_elapsed,

    budget_rev: $json.budget_rev || 0,
    budget_margin: $json.budget_margin || 0,
    budget_payroll: $json.budget_payroll || 0,

    rev: {
      cur:   sumFromTotals(totalsCur,   REVENUE_ROOTS),
      prior: sumFromTotals(totalsPrior, REVENUE_ROOTS),
      ytd:   sumFromTotals(totalsYtd,   REVENUE_ROOTS),
    },
    rev_for_margin: {
      cur:   sumFromTotals(totalsCur,   MARGIN_REV_ROOTS),
      prior: sumFromTotals(totalsPrior, MARGIN_REV_ROOTS),
      ytd:   sumFromTotals(totalsYtd,   MARGIN_REV_ROOTS),
    },
    cogs: {
      cur:   sumFromTotals(totalsCur,   COGS_ROOTS),
      prior: sumFromTotals(totalsPrior, COGS_ROOTS), 
      ytd:   sumFromTotals(totalsYtd,   COGS_ROOTS),
    },
    payroll: {
      cur:   sumFromTotals(totalsCur,   PAYROLL_ROOTS),
      prior: sumFromTotals(totalsPrior, PAYROLL_ROOTS), 
      ytd:   sumFromTotals(totalsYtd,   PAYROLL_ROOTS),
    },
    cash: {
      cur:   sumFromTotals(totalsCur,   CASH_ROOTS),
      prior: sumFromTotals(totalsPrior, CASH_ROOTS), 
      ytd:   sumFromTotals(totalsYtd,   CASH_ROOTS),
    },
};

const allItems = $input.all();
if (!allItems.length) return [];

const fmt = (val) => val !== null && val !== undefined
  ? new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(val)
  : null;

const MONTH_LABELS = ['Janv.','Févr.','Mars','Avr.','Mai','Juin','Juil.','Août','Sept.','Oct.','Nov.','Déc.'];

const fy_n  = allItems[0].json.fy_n;
const fy_n1 = allItems[0].json.fy_n1;

const startMonth = fy_n ? parseInt(fy_n.substring(4, 6), 10) : 1;
const orderedMonths = Array.from({ length: 12 }, (_, i) => {
  const m = startMonth + i;
  return m > 12 ? m - 12 : m;
});

const byMonthN  = {};
const byMonthN1 = {};

for (const item of allItems) {
  const monthNum = parseInt(item.json.calendar_month.split('-')[1], 10);
  if (item.json.n)  byMonthN[monthNum]  = item.json.n;
  if (item.json.n1) byMonthN1[monthNum] = item.json.n1;
}

const dataN  = orderedMonths.map(m => byMonthN[m]?.has_data  ? byMonthN[m].balance  : null);
const dataN1 = orderedMonths.map(m => byMonthN1[m]?.has_data ? byMonthN1[m].balance : null);

const chartConfig = {
  type: 'line',
  data: {
    labels: orderedMonths.map(m => MONTH_LABELS[m - 1]),
    datasets: [
      {
        label:                'Trésorerie N',
        data:                 dataN,
        borderColor:          '#1A1A2E',
        backgroundColor:      'rgba(27,67,50,0.08)',
        borderWidth:          2.5,
        pointRadius:          4,
        pointBackgroundColor: '#1A1A2E',
        tension:              0.3,
        spanGaps:             true,
        fill:                 false,
      },
      {
        label:                'Trésorerie N-1',
        data:                 dataN1,
        borderColor:          '#E9A800',
        backgroundColor:      'rgba(233,168,0,0.08)',
        borderWidth:          2,
        borderDash:           [6, 4],
        pointRadius:          3,
        pointBackgroundColor: '#E9A800',
        tension:              0.3,
        spanGaps:             true,
        fill:                 false,
      },
    ],
  },
  options: {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text:    'Comparaison trésorerie N-1 vs N',
        font:    { size: 14 },
        color:   '#1A1A2E',
        padding: { bottom: 16 },
      },
      legend: { position: 'top' },
    },
    scales: {
      y: { ticks: { callback: (val) => fmt(val) } },
    },
  },
};

return [{
  json: {
    chart_config: chartConfig,
    months: orderedMonths.map(m => ({
      month:          m,
      balance_n:      byMonthN[m]?.balance  ?? null,
      balance_n1:     byMonthN1[m]?.balance ?? null,
      has_data_n:     byMonthN[m]?.has_data  ?? false,
      has_data_n1:    byMonthN1[m]?.has_data ?? false,
    })),
  },
}];

const CASH_ROOTS  = ["512", "53"];
const EXCL_ROOTS  = ["580"];
const round2 = (n) => Math.round(n * 100) / 100;

const entries = $json.entries ?? [];

const cashEntries = entries.filter(e => {
  const num = String(e.formatted_number || e.number || "");
  const isCash    = CASH_ROOTS.some(r => num.startsWith(r));
  const isExcluded = EXCL_ROOTS.some(r => num.startsWith(r));
  return isCash && !isExcluded;
});

const monthCash = cashEntries.length
  ? round2(cashEntries.reduce((sum, e) => sum + ((Number(e.debits) || 0) - (Number(e.credits) || 0)), 0))
  : null;

return {
  fiscal_year:       $json.fiscal_year,
  period:            $json.period,
  calendar_month:    $json.period.start.substring(0, 7),
  monthCash,
  has_data:          entries.length > 0,
  native_carry_over: $json.native_carry_over ?? true,
};

const items = $input.all().map(i => i.json);
if (!items.length) return [];

const round2 = (n) => Math.round(n * 100) / 100;

const byFY = {};
for (const item of items) {
  const fy = item.fiscal_year?.start;
  if (!fy) continue;
  (byFY[fy] ??= []).push(item);
}

const fyKeys = Object.keys(byFY).sort();
if (!fyKeys.length) return [];

const fy_n1 = fyKeys[0];
const fy_n  = fyKeys[1] ?? fyKeys[0];

const mergeByMonth = (fyItems) => {
  const byMonth = {};
  for (const item of fyItems) {
    const key = item.calendar_month;
    if (!byMonth[key]) byMonth[key] = { ...item, monthCash: null };
    if (item.monthCash !== null)
      byMonth[key].monthCash = round2((byMonth[key].monthCash ?? 0) + item.monthCash);
    if (item.has_data) byMonth[key].has_data = true;
  }
  return Object.values(byMonth).sort((a, b) => a.period.start.localeCompare(b.period.start));
};

const processSeries = (fyStart, carryOver = null) => {
  const months = mergeByMonth(byFY[fyStart] || []);
  const result = {};
  let balance = null;

  months.forEach((m, i) => {
    const cash = m.monthCash ?? null;
    let movement = cash;

    if (i === 0) {
      if (carryOver !== null) {
        if (m.native_carry_over) {
          // API returns absolute balance — movement is the delta vs carry-over
          balance  = cash;
          movement = cash !== null ? round2(cash - carryOver) : null;
        } else {
          // API returns a movement — add it to carry-over
          balance  = cash !== null ? round2(carryOver + cash) : carryOver;
        }
      } else {
        balance  = cash;
        movement = null;
      }
    } else {
      if (cash !== null)
        balance = balance !== null ? round2(balance + cash) : cash;
    }

    result[m.calendar_month] = {
      period_start:   m.period.start,
      calendar_month: m.calendar_month,
      balance,
      movement,
      has_data: m.has_data,
    };
  });

  return result;
};

const dataN1 = processSeries(fy_n1);

let carryOver = null;
if (fy_n1 !== fy_n) {
  const lastMonth = Object.keys(dataN1).sort().at(-1);
  if (lastMonth) carryOver = dataN1[lastMonth].balance;
}

const dataN = processSeries(fy_n, carryOver);

const allMonths = [...new Set([...Object.keys(dataN1), ...Object.keys(dataN)])].sort();

return allMonths.map(month => ({
  json: {
    calendar_month: month,
    n:    dataN[month]  ?? null,
    n1:   dataN1[month] ?? null,
    fy_n,
    fy_n1,
  }
}));
